   859  int
   860  cdf_find_stream(const cdf_dir_t *dir, const char *name, int type)
   861  {
   862          size_t i, name_len = strlen(name) + 1;
   863
   864          for (i = dir->dir_len; i > 0; i--)
   865                  if (dir->dir_tab[i - 1].d_type == type &&
   866                      cdf_namecmp(name, dir->dir_tab[i - 1].d_name, name_len)
   867                      == 0)
   868                       break;
   869          if (i > 0)
   870                  return CAST(int, i);
   871
   872          DPRINTF(("Cannot find type %d `%s'\n", type, name));
   873          errno = ESRCH;
   874          return 0;
   875  }
