   886  static const uint8_t *
   887  cdf_get_property_info_pos(const cdf_stream_t *sst, const cdf_header_t *h,
   888      const uint8_t *p, const uint8_t *e, size_t i)
   889  {
   890          size_t tail = (i << 1) + 1;
   891          size_t ofs;
   892
   893          if (p >= e) {
   894                  DPRINTF(("Past end %p < %p\n", e, p));
   895                  return NULL;
   896          }
   897
   898          if (cdf_check_stream_offset(sst, h, p, (tail + 1) * sizeof(uint32_t),
   899              __LINE__) == -1)
   900                  return NULL;
   901
   902          ofs = CDF_GETUINT32(p, tail);
   903          if (ofs < 2 * sizeof(uint32_t)) {
   904                  DPRINTF(("Offset too small %zu\n", ofs));
   905                  return NULL;
   906          }
   907
   908          ofs -= 2 * sizeof(uint32_t);
   909          if (ofs > CAST(size_t, e - p)) {
   910                  DPRINTF(("Offset too big %zu %td\n", ofs, e - p));
   911                  return NULL;
   912          }
   913
   914          return CAST(const uint8_t *, cdf_offset(CAST(const void *, p), ofs));
   915  }
