   971  int
   972  cdf_read_property_info(const cdf_stream_t *sst, const cdf_header_t *h,
   973      uint32_t offs, cdf_property_info_t **info, size_t *count, size_t *maxcount)
   974  {
   975          const cdf_section_header_t *shp;
   976          cdf_section_header_t sh;
   977          const uint8_t *p, *q, *e;
   978          size_t i, o4, nelements, j, slen, left;
   979          cdf_property_info_t *inp;
   980
   981          if (offs > UINT32_MAX / 4) {
   982                  errno = EFTYPE;
   983                  goto out;
   984          }
   985          shp = CAST(const cdf_section_header_t *,
   986              cdf_offset(sst->sst_tab, offs));
   987          if (cdf_check_stream_offset(sst, h, shp, sizeof(*shp), __LINE__) == -1)
   988                  goto out;
   989          sh.sh_len = CDF_TOLE4(shp->sh_len);
   990          if (sh.sh_len > CDF_SHLEN_LIMIT) {
   991                  errno = EFTYPE;
   992                  goto out;
   993          }
   994
   995          if (cdf_check_stream_offset(sst, h, shp, sh.sh_len, __LINE__) == -1)
   996                  goto out;
   997
   998          sh.sh_properties = CDF_TOLE4(shp->sh_properties);
   999          DPRINTF(("section len: %u properties %u\n", sh.sh_len,
  1000              sh.sh_properties));
  1001          if (sh.sh_properties > CDF_PROP_LIMIT)
  1002                  goto out;
  1003          inp = cdf_grow_info(info, maxcount, sh.sh_properties);
  1004          if (inp == NULL)
  1005                  goto out;
  1006          inp += *count;
  1007          *count += sh.sh_properties;
  1008          p = CAST(const uint8_t *, cdf_offset(sst->sst_tab, offs + sizeof(sh)));
  1009          e = CAST(const uint8_t *, cdf_offset(shp, sh.sh_len));
  1010          if (p >= e || cdf_check_stream_offset(sst, h, e, 0, __LINE__) == -1)
  1011                  goto out;
  1012
  1013          for (i = 0; i < sh.sh_properties; i++) {
  1014                  if ((q = cdf_get_property_info_pos(sst, h, p, e, i)) == NULL)
  1015                       goto out;
  1016                  inp[i].pi_id = CDF_GETUINT32(p, i << 1);
  1017                  left = CAST(size_t, e - q);
  1018                  if (left < sizeof(uint32_t)) {
  1019                       DPRINTF(("short info (no type)_\n"));
  1020                       goto out;
  1021                  }
  1022                  inp[i].pi_type = CDF_GETUINT32(q, 0);
  1023                  DPRINTF(("%" SIZE_T_FORMAT "u) id=%#x type=%#x offs=%#tx,%#x\n",
  1024                      i, inp[i].pi_id, inp[i].pi_type, q - p, offs));
  1025                  if (inp[i].pi_type & CDF_VECTOR) {
  1026                       if (left < sizeof(uint32_t) * 2) {
  1027                          DPRINTF(("missing CDF_VECTOR length\n"));
  1028                          goto out;
  1029                       }
  1030                       nelements = CDF_GETUINT32(q, 1);
  1031                       if (nelements > CDF_ELEMENT_LIMIT || nelements == 0) {
  1032                          DPRINTF(("CDF_VECTOR with nelements == %"
  1033                              SIZE_T_FORMAT "u\n", nelements));
  1034                          goto out;
  1035                       }
  1036                       slen = 2;
  1037                  } else {
  1038                       nelements = 1;
  1039                       slen = 1;
  1040                  }
