  1091
  1092                          DPRINTF(("o=%" SIZE_T_FORMAT "u l=%d(%"
  1093                              SIZE_T_FORMAT "u), t=%" SIZE_T_FORMAT
  1094                              "u s=%s\n", o4, l, CDF_ROUND(l, sizeof(l)),
  1095                              left, inp[i].pi_str.s_buf));
  1096
  1097                          if (l & 1)
  1098                                  l++;
  1099
  1100                          slen += l >> 1;
  1101                          o4 = slen * sizeof(uint32_t);
  1102                       }
