   644          for (j = i = 0; sid >= 0; i++, j++) {
   645                  if (j >= CDF_LOOP_LIMIT) {
   646                       DPRINTF(("Read short sector chain loop limit"));
   647                       goto out;
   648                  }
   649                  if (i >= scn->sst_len) {
   650                       DPRINTF(("Out of bounds reading short sector chain "

650                       DPRINTF(("Out of bounds reading short sector chain "
   651                           "%" SIZE_T_FORMAT "u > %" SIZE_T_FORMAT "u\n",
   652                           i, scn->sst_len));
