   736  int
   737  cdf_read_ssat(const cdf_info_t *info, const cdf_header_t *h,
   738      const cdf_sat_t *sat, cdf_sat_t *ssat)
   739  {
   740          size_t i, j;
   741          size_t ss = CDF_SEC_SIZE(h);
   742          cdf_secid_t sid = h->h_secid_first_sector_in_short_sat;
   743
   744          ssat->sat_tab = NULL;
   745          ssat->sat_len = cdf_count_chain(sat, sid, ss);
   746          if (ssat->sat_len == CAST(size_t, -1))
   747                  goto out;
   748
   749          ssat->sat_tab = CAST(cdf_secid_t *, CDF_CALLOC(ssat->sat_len, ss));
   750          if (ssat->sat_tab == NULL)
   751                  goto out1;
   752
   753          for (j = i = 0; sid >= 0; i++, j++) {
   754                  if (j >= CDF_LOOP_LIMIT) {
   755                       DPRINTF(("Read short sat sector loop limit"));
   756                       goto out;
   757                  }
   758                  if (i >= ssat->sat_len) {
   759                       DPRINTF(("Out of bounds reading short sector chain "
   760                           "%" SIZE_T_FORMAT "u > %" SIZE_T_FORMAT "u\n", i,
   761                           ssat->sat_len));
   762                       goto out;
   763                  }
   764                  if (cdf_read_sector(info, ssat->sat_tab, i * ss, ss, h, sid) !=
   765                      CAST(ssize_t, ss)) {
   766                       DPRINTF(("Reading short sat sector %d", sid));
   767                       goto out1;
   768                  }
   769                  sid = CDF_TOLE4(CAST(uint32_t, sat->sat_tab[sid]));
   770          }
   771          return 0;
   772  out:
   773          errno = EFTYPE;
   774  out1:
   775          free(ssat->sat_tab);
   776          return -1;
   777  }
